6	import React, { useState, useEffect, useRef } from 'react';
7	import { supabase } from './lib/supabase';
8	import { maskRealName } from './utils/maskName';
9	import { trackBackEvent } from './utils/trackBackEvent';
10	import { trackFunnelEvent } from './utils/trackFunnelEvent';
11	import { Header } from './components/Header';
12	import { EventBanner } from './components/EventBanner';
13	import { AppointmentReminders } from './components/AppointmentReminders';
14	import { EventsView } from './components/EventsView';
15	import { RequestTab } from './components/CompanionRequests';
16	import { sampleEventsForMonth } from './data/events';
17	import { DEMO_USER_ID } from './data/demoIdentity';
18	import { appointmentStart, koreaDateParts } from './utils/calendar';
19	import { completionAvailability, formatMeetupRange, isValidMeetupRange } from './utils/meetupLifecycle';
20	import { CategoryGrid } from './components/CategoryGrid';
21	import { BottomNav, NavTab } from './components/BottomNav';
22	import { DashboardModal } from './components/DashboardModal';
23	import { EventDetailModal } from './components/EventDetailModal';
24	import { CategoryDetailModal } from './components/CategoryDetailModal';
25	import { CreateMeetupModal } from './components/CreateMeetupModal';
26	
27	import { NotificationModal } from './components/NotificationModal';
28	import { AuthModal } from './components/AuthModal';
29	import { KycAuthModal } from './components/KycAuthModal';
30	import { PostDetailModal } from './components/PostDetailModal';
31	import { JoinRequestModal } from './components/JoinRequestModal';
32	import { SafetyRulesModal } from './components/SafetyRulesModal';
33	import { VoiceCallModal } from './components/VoiceCallModal';
34	import { ReportModal } from './components/ReportModal';
35	import { ReviewModal } from './components/ReviewModal';
36	import { EscrowPaymentModal } from './components/EscrowPaymentModal';
37	import { ExploreView } from './components/ExploreView';
38	import { ChatView } from './components/ChatView';
39	import { ChatListView } from './components/ChatListView';
40	import { UserProfileModal } from './components/UserProfileModal';
41	import { publicProfileForMember } from './data/publicProfiles';
42	import { CancellationDialog, LifecycleConfirmDialog, ScheduleConflictDialog } from './components/LifecycleDialogs';
43	import { cancelAppointment as cancelConfirmedAppointment, closePost, conditionsOf, confirmChangedConditions, expirePosts, isConfirmedAppointment, isOpenRequest, isRecruiting, overlappingAppointments, recruitmentDeadline, updateRecruitingPost, type LifecycleState } from './utils/postLifecycle';
44	import { acceptRequest, createRequestRoom, requestRoomId, roomAccess } from './utils/conversations';
45	import { MyPageView } from './components/MyPageView';
46	
47	import {
48	  mockAppointments,
49	  mockCategories,
50	  mockMeetupPosts,
51	  mockNotifications,
52	} from './data/mockData';
53	import { Appointment, CategoryItem, EventBannerItem, MeetupPost, CurrentUser, JoinRequest, ReviewItem, EscrowPayment, NotificationItem, ChatRoom, PublicUserProfile, ScheduleProposal } from './types';
54	
55	type ConflictAction =
56	  | { kind: 'join'; postId: string; message: string }
57	  | { kind: 'accept'; requestId: string; simulateHost: boolean }
58	  | { kind: 'proposal'; roomId: string; messageId: string; accepted: boolean; sample: boolean }
59	  | { kind: 'create'; post: MeetupPost };
60	
61	export default function App() {
62	  // Navigation state
63	  const [activeTab, setActiveTab] = useState<NavTab>('home');
64	
65	  // User Auth state (Supabase Auth 연동)
66	  const [currentUser, setCurrentUser] = useState<CurrentUser | null>(null);
67	
68	  useEffect(() => {
69	    // 1. 초기 세션 확인
70	    supabase.auth.getSession().then(({ data: { session } }) => {
71	      if (session?.user) {
72	        const meta = session.user.user_metadata || {};
73	        const name = meta.realName || '유미당 회원';
74	        const masked = meta.maskedName || maskRealName(name);
75	        setCurrentUser({
76	          id: session.user.id,
77	          isLoggedIn: true,
78	          email: session.user.email,
79	          phone: session.user.phone || '010-0000-0000',
80	          realName: name,
81	          maskedName: masked,
82	          nickname: masked,
83	          gender: meta.gender || 'female',
84	          ageGroup: meta.ageGroup || '20대',
85	          neighborhood: meta.neighborhood || '서울 강남구 역삼동',
86	          sugarContent: 50,
87	          isPhoneVerified: false,
88	          isKycVerified: false,
89	          avatar: meta.avatar || 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=300&q=80',
90	          bio: meta.bio || '유미당과 함께하는 따뜻한 동행입니다.',
91	          joinedAt: '2026.09',
92	        });
93	      }
94	    });
95	
96	    // 2. Auth 상태 변화 리스너
97	    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
98	      if (session?.user) {
99	        const meta = session.user.user_metadata || {};
100	        const name = meta.realName || '유미당 회원';
101	        const masked = meta.maskedName || maskRealName(name);
102	        setCurrentUser({
103	          id: session.user.id,
104	          isLoggedIn: true,
105	          email: session.user.email,
106	          phone: session.user.phone || '010-0000-0000',
107	          realName: name,
108	          maskedName: masked,
109	          nickname: masked,
110	          gender: meta.gender || 'female',
111	          ageGroup: meta.ageGroup || '20대',
112	          neighborhood: meta.neighborhood || '서울 강남구 역삼동',
113	          sugarContent: 50,
114	          isPhoneVerified: false,
115	          isKycVerified: false,
116	          avatar: meta.avatar || 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=300&q=80',
117	          bio: meta.bio || '유미당과 함께하는 따뜻한 동행입니다.',
118	          joinedAt: '2026.09',
119	        });
120	      } else {
121	        setCurrentUser(null);
122	      }
123	    });
124	
125	    return () => subscription.unsubscribe();
126	  }, []);
127	
128	  // Modal states
129	  const [isDashboardOpen, setIsDashboardOpen] = useState(false);
130	  const [isNotificationsOpen, setIsNotificationsOpen] = useState(false);
131	  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
132	  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
133	  const [isKycModalOpen, setIsKycModalOpen] = useState(false);
134	  const [selectedEvent, setSelectedEvent] = useState<EventBannerItem | null>(null);
135	  const [selectedCategory, setSelectedCategory] = useState<CategoryItem | null>(null);
136	
137	  // Phase 2: Post Detail & Editing states
138	  const [selectedPostForDetail, setSelectedPostForDetail] = useState<MeetupPost | null>(null);
139	  const [editingPost, setEditingPost] = useState<MeetupPost | null>(null);
140	
141	  // Phase 3: 1:1 Matching Requests & Modals
142	  const [isJoinRequestModalOpen, setIsJoinRequestModalOpen] = useState(false);
143	  const [selectedPostForJoin, setSelectedPostForJoin] = useState<MeetupPost | null>(null);
144	  const [requestTab, setRequestTab] = useState<RequestTab>('sent');
145	  const [isEventsOpen, setIsEventsOpen] = useState(false);
146	  const [now, setNow] = useState(() => new Date());
147	  useEffect(() => {
148	    const timer = setInterval(() => setNow(new Date()), 60_000);
149	    return () => clearInterval(timer);
150	  }, []);
151	  const today = koreaDateParts(now);
152	  const eventBanners = sampleEventsForMonth(today.year, today.month);
153	
154	  // Phase 4: Safety, Voice Call & Emergency Report states
155	  const [isSafetyRulesOpen, setIsSafetyRulesOpen] = useState(false);
156	  const [isVoiceCallOpen, setIsVoiceCallOpen] = useState(false);
157	  const [isReportOpen, setIsReportOpen] = useState(false);
158	
159	  // Phase 5: Mutual Blind Review & Sugar Settling states
160	  const [isReviewModalOpen, setIsReviewModalOpen] = useState(false);
161	  const [reviewAppointmentId, setReviewAppointmentId] = useState<string | null>(null);
162	  const [submittedReviews, setSubmittedReviews] = useState<Record<string, { rating: number; badges: string[]; comment: string }>>({});
163	  const submissionLocks = useRef(new Set<string>());
164	  const settlementLocks = useRef(new Set<string>());
165	
166	  // UI 뒤로가기/닫기 이벤트 및 체류시간 실시간 추적 (Supabase 정규화 테이블 ui_back_events)
167	  const modalOpenTimes = useRef<Record<string, number>>({});
168	
169	  useEffect(() => {
170	    if (selectedPostForDetail) {
