  | 'ESCROW_PAYMENT'    // 에스크로 결제 모달
  | 'HOME_TAB'          // 홈 탭
  | 'EXPLORE_TAB'       // 탐색 탭
  | 'CHAT_TAB'          // 채팅 탭
  | 'MY_PAGE_TAB';      // 마이페이지 탭

export type UIActionType = 'back' | 'close' | 'backdrop' | 'swipe';

