                    </label>
                    <div className="flex gap-1.5">
                      {(['female', 'male'] as const).map((g) => (
                        <button
                          type="button"
                          key={g}
                          onClick={() => handleGenderChange(g)}
                          className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all ${
                            gender === g
                              ? 'bg-[#f0edff] text-[#6c2cf5] border border-[#6c2cf5]/30'
