                      </button>
                    </div>
                    <p className="text-[11px] text-blue-700/90 leading-tight">
                      * 1:1 동행 안전 보증을 위해 남성 회원은 기존 보증 회원의 추천인 코드가 필수입니다.
                    </p>
                  </div>
                )}

                {/* 당도 안내 */}
                <div className="p-3.5 bg-[#f8f6ff] rounded-2xl flex items-center justify-between text-xs">
                  <div className="flex items-center gap-2">
                    <span className="text-base">🍯</span>
                    <div>
                      <span className="font-bold text-gray-900 block">기본 시작 당도</span>
                      <span className="text-[11px] text-gray-500">동행 완료 후 상호 평가로 상승합니다</span>
                    </div>
                  </div>
                  <span className="font-extrabold text-[#6c2cf5] text-sm bg-white px-2.5 py-1 rounded-lg shadow-2xs">
                    50 🍯
                  </span>
                </div>

                <button
                  type="submit"
                  className="w-full py-3.5 bg-[#6c2cf5] hover:bg-[#5820d8] text-white font-bold rounded-xl text-[15px] shadow-md shadow-purple-500/25 active:scale-98 transition-all"
                >
                  회원가입 완료 및 서비스 시작
                </button>
              </form>
            )}
          </div>
        )}

        {/* ==============================
            MODE 2: SIGN IN (로그인)
        ============================== */}
        {mode === 'signin' && (
          <div className="p-5 space-y-4">
            <div>
              <label className="block text-xs font-bold text-gray-700 mb-1.5">
                가입된 휴대폰 번호
              </label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <Phone className="w-4 h-4 text-gray-400 absolute left-3.5 top-3" />
                  <input
                    type="tel"
                    maxLength={11}
                    inputMode="numeric"
                    autoComplete="tel"
                    aria-label="휴대폰 번호"
                    placeholder="01012345678"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value.replace(/\D/g, '').slice(0, 11))}
                    onPaste={(e) => { e.preventDefault(); setPhone(e.clipboardData.getData('text').replace(/\D/g, '').slice(0, 11)); }}
                    className="w-full pl-10 pr-3.5 py-2.5 rounded-xl bg-gray-50 focus:bg-white text-sm border border-gray-200 focus:outline-none focus:ring-2 focus:ring-[#6c2cf5]/30 focus:border-[#6c2cf5]"
                  />
                </div>
                <button
                  type="button"
                  onClick={handleSendOtp}
                  className="px-3.5 py-2.5 bg-[#f0edff] hover:bg-[#ded6fb] text-[#6c2cf5] font-bold text-xs rounded-xl transition-colors whitespace-nowrap"
                >
                  {otpSent ? '재발송' : '인증번호 발송'}
                </button>
              </div>
            </div>

            {otpSent && (
              <div className="space-y-2.5 animate-in fade-in">
                <div className="flex items-center justify-between">
                  <label className="block text-xs font-bold text-gray-700">
                    인증번호 6자리
                  </label>
                  <span className="text-xs font-semibold text-rose-500 flex items-center gap-1">
                    <Clock className="w-3.5 h-3.5" />
                    남은 시간 {Math.floor(timerSeconds / 60)}:{('0' + (timerSeconds % 60)).slice(-2)}
                  </span>
                </div>

                <div className="relative">
                  <input
                    type="text"
                    maxLength={6}
                    placeholder="인증번호 6자리 입력"
                    value={otpCode}
                    onChange={(e) => setOtpCode(e.target.value)}
                    className="w-full px-3.5 py-2.5 rounded-xl bg-gray-50 focus:bg-white text-sm tracking-widest font-mono text-center font-bold border border-gray-200 focus:outline-none focus:ring-2 focus:ring-[#6c2cf5]/30 focus:border-[#6c2cf5]"
                  />
                  <button
                    type="button"
                    onClick={() => setOtpCode('123456')}
                    className="absolute right-2 top-2 px-2 py-1 text-[11px] font-bold text-[#6c2cf5] bg-[#f0edff] hover:bg-[#ded6fb] rounded-lg transition-colors"
                  >
                    테스트코드 입력
                  </button>
                </div>

                <button
                  type="button"
                  disabled={otpCode.trim().length !== 6}
                  onClick={() => handleVerifyOtp(true)}
                  className="w-full mt-2 py-3.5 bg-[#6c2cf5] hover:bg-[#5820d8] disabled:bg-purple-300 text-white font-bold rounded-xl text-[15px] shadow-md shadow-purple-500/25 active:scale-98 transition-all flex items-center justify-center gap-2"
                >
                  <span>인증 확인 및 로그인</span>
                  <ArrowRight className="w-4 h-4" />
                </button>
              </div>
            )}

            <div className="pt-2 text-center">
              <button
                type="button"
                onClick={() => {
                  resetForm();
                  setMode('signup');
                  setStep('terms');
                  setErrorMessage('');
                  setInfoMessage('');
                }}
                className="text-xs text-gray-500 hover:text-[#6c2cf5] font-medium"
              >
                계정이 없으신가요? <span className="underline font-bold text-[#6c2cf5]">휴대폰 본인인증으로 가입</span>
              </button>
            </div>
          </div>
        )}
        {mode === 'signup' && <div className="pb-5 text-center"><button onClick={resetForm} className="text-xs text-gray-500">이미 계정이 있으신가요? <span className="text-[#6c2cf5] font-bold underline">로그인으로 돌아가기</span></button></div>}
      </div>
    </div>
  );
};

import { postStatusLabel } from '../utils/postLifecycle';
import { CompanionRequests, RequestTab } from './CompanionRequests';
import React, { useState, useRef } from 'react';
import { User, Heart, Calendar, ShieldCheck, ChevronRight, Settings, Star, Award, LogOut, Sparkles, MessageSquare, Clock, Lock, CreditCard, Camera } from 'lucide-react';
import { Appointment, CurrentUser, MeetupPost, ReviewItem, EscrowPayment, JoinRequest } from '../types';

interface MyPageViewProps {
  appointments: Appointment[];
  onOpenDashboard: (appointment: Appointment) => void;
  requests: JoinRequest[];
  requestTab: RequestTab;
  onChangeRequestTab: (tab: RequestTab) => void;
  onAcceptRequest: (id: string) => void;
  onRejectRequest: (id: string) => void;
  onOpenRequestPost: (id: string) => void;
  onOpenRequestChat: (id: string) => void;
  onOpenRequestProfile: (id: string) => void;
  onCancelRequest: (id: string) => void;
  onReconfirmRequest: (id: string, revision: number, agree: boolean, simulate?: boolean) => void;
  posts: MeetupPost[];
  onOpenOwnPost: (id: string) => void;
  currentUser: CurrentUser | null;
  onOpenAuth: () => void;
  onOpenKyc: () => void;
  onLogout: () => void;
  onUpdateAvatar?: (avatar: string) => void;
  reviews?: ReviewItem[];
  escrowPayments?: EscrowPayment[];
}

export const MyPageView: React.FC<MyPageViewProps> = ({
  appointments, requests, requestTab, onChangeRequestTab, onAcceptRequest, onRejectRequest, onOpenRequestPost, onOpenRequestChat, onOpenRequestProfile, onCancelRequest, onReconfirmRequest, posts, onOpenOwnPost,
  onOpenDashboard,
  currentUser,
  onOpenAuth,
  onOpenKyc,
  onLogout,
  onUpdateAvatar,
  reviews = [],
  escrowPayments = [],
}) => {
  const [activeSubTab, setActiveSubTab] = useState<'info' | 'reviews' | 'escrow'>('info');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleAvatarChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && onUpdateAvatar) {
      if (file.size > 5 * 1024 * 1024) {
        alert('사진 파일 크기는 5MB 이하여야 합니다.');
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === 'string') {
          onUpdateAvatar(reader.result);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  if (!currentUser || !currentUser.isLoggedIn) {
    return (
      <div className="px-5 pt-12 pb-24 text-center space-y-4">
        <div className="w-16 h-16 rounded-full bg-[#f0edff] text-[#6c2cf5] flex items-center justify-center mx-auto shadow-sm">
          <ShieldCheck className="w-8 h-8" />
        </div>
        <h3 className="text-lg font-bold text-gray-900">로그인이 필요한 서비스입니다</h3>
        <p className="text-xs text-gray-500 max-w-[280px] mx-auto leading-relaxed">
          유미당은 신뢰할 수 있는 1:1 동행을 위해 간단한 휴대폰 본인확인 후 이용하실 수 있습니다.
        </p>
        <button
          onClick={onOpenAuth}
          className="w-full max-w-xs mx-auto py-3.5 bg-[#6c2cf5] text-white font-bold rounded-xl text-sm shadow-md shadow-purple-500/20 active:scale-98 transition-all"
        >
          휴대폰 본인인증으로 시작하기
        </button>
      </div>
    );
  }

  const diffSugar = Math.round(currentUser.sugarContent - 50);

  return (
    <div className="px-5 pt-3 pb-24 text-left space-y-4">
      <div className="-mx-5 -mt-3"><CompanionRequests userId={currentUser.id} requests={requests} tab={requestTab} onChangeTab={onChangeRequestTab} onAccept={onAcceptRequest} onReject={onRejectRequest} onOpenPost={onOpenRequestPost} onOpenChat={onOpenRequestChat} onOpenProfile={onOpenRequestProfile} onCancel={onCancelRequest} onReconfirm={onReconfirmRequest} /></div>
      <section aria-label="내가 쓴 공고" className="bg-white rounded-2xl p-4"><h2 className="text-sm font-bold mb-3">내가 쓴 공고</h2>{posts.filter(post => post.authorId === currentUser.id && post.status !== 'deleted').length === 0 ? <p className="text-xs text-gray-500">아직 작성한 공고가 없어요.</p> : posts.filter(post => post.authorId === currentUser.id && post.status !== 'deleted').map(post => <button key={post.id} onClick={() => onOpenOwnPost(post.id)} className="w-full text-left py-3 border-b border-gray-100 text-xs"><b className="block">{post.title}</b><span className="block text-gray-500 mt-1">{postStatusLabel(post)} · {post.time}</span></button>)}</section>
      {/* Profile Card */}
      <div className="bg-white rounded-[24px] p-5 shadow-[0_2px_14px_rgba(0,0,0,0.03)]">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3.5">
            <div
