        <button
          onClick={() => setActiveSubTab('info')}
          className={`flex-1 py-2 rounded-xl transition-all ${
            activeSubTab === 'info'
              ? 'bg-white text-gray-900 shadow-xs'
              : 'text-gray-500 hover:text-gray-900'
          }`}
        >
          동행 정보
        </button>
        <button
