    trackFunnelEvent({
      step: 'JOIN_REQUEST_OPEN',
      targetPostId: post.id,
      pageKey: 'JOIN_REQUEST',
    });

    setSelectedPostForJoin(post);
    setSelectedPostForDetail(null);
    setSelectedEvent(null);
    setSelectedCategory(null);
    setIsJoinRequestModalOpen(true);
