      modalOpenTimes.current['JOIN_REQUEST'] = Date.now();
    } else if (modalOpenTimes.current['JOIN_REQUEST']) {
      const durationMs = Date.now() - modalOpenTimes.current['JOIN_REQUEST'];
      delete modalOpenTimes.current['JOIN_REQUEST'];
